}): SubmissionRoundContext => ({
  roundId: RoundId.make(`test-${input.pulseId}`),
  pulseName: input.pulseName,
  minimumGroupSize: input.minimumGroupSize,
  questions: input.questions.map((question, position) => ({
    id: question.id,
    position,
    text: question.text,
